const C = (o) => o;
// Each person's numbers (age, nerve and the rest) and their week are in rules.js, under people and schedules.
const PEOPLE = RULES.people;
const week = (id) =>
  RULES.schedules[id].map((r) =>
    r.onDayIndexes
      ? [r.fromHour, r.place, r.doing, r.onDayIndexes]
      : r.doing !== undefined
        ? [r.fromHour, r.place, r.doing]
        : [r.fromHour, r.place],
  );

